13	typedef struct sdmmc_desc_s {
14	    struct {
15	        uint32_t reserved1: 1;
16	        uint32_t disable_int_on_completion: 1;
17	        uint32_t last_descriptor: 1;
18	        uint32_t first_descriptor: 1;
19	        uint32_t second_address_chained: 1;
20	        uint32_t end_of_ring: 1;
21	        uint32_t reserved2: 24;
22	        uint32_t card_error_summary: 1;
23	        uint32_t owned_by_idmac: 1;
24	    };
25	    struct {
26	        uint32_t buffer1_size: 13;
27	        uint32_t buffer2_size: 13;
28	        uint32_t reserved3: 6;
29	    };
30	    void* buffer1_ptr;
31	    union {
32	        void* buffer2_ptr;
33	        void* next_desc_ptr;
34	    };
35	    /**
36	     * These `reserved[12]` are for cache alignment. On P4, L1 Cache alignment is 64B.
37	     * For those who want to access the DMA descriptor in a non-cacheable way, you can
38	     * consider remove these `reserved[12]` bytes.
39	     */
40	    uint32_t reserved[12];
41	} sdmmc_desc_t;
42	
43	#define SDMMC_DMA_MAX_BUF_LEN 4096
44	
45	#ifndef __cplusplus
46	_Static_assert(sizeof(sdmmc_desc_t) == 64, "invalid size of sdmmc_desc_t structure");
47	#endif
