49	/** Group: Control register */
50	/** Type of ctrl register
51	 *  Control register
52	 */
53	typedef union {
54	    struct {
55	        /** controller_reset : R/W; bitpos: [0]; default: 0;
56	         *  To reset controller, firmware should set this bit. This bit is auto-cleared after
57	         *  two AHB and two sdhost_cclk_in clock cycles.
58	         */
59	        uint32_t controller_reset:1;
60	        /** fifo_reset : R/W; bitpos: [1]; default: 0;
61	         *  To reset FIFO, firmware should set bit to 1. This bit is auto-cleared after
62	         *  completion of reset operation.
63	         *  Note: FIFO pointers will be out of reset after 2 cycles of system clocks in
64	         *  addition to synchronization delay (2 cycles of card clock), after the fifo_reset is
65	         *  cleared.
66	         */
67	        uint32_t fifo_reset:1;
68	        /** dma_reset : R/W; bitpos: [2]; default: 0;
69	         *  To reset DMA interface, firmware should set bit to 1. This bit is auto-cleared
70	         *  after two AHB clocks.
71	         */
72	        uint32_t dma_reset:1;
73	        uint32_t reserved_3:1;
74	        /** int_enable : R/W; bitpos: [4]; default: 0;
75	         *  Global interrupt enable/disable bit. 0: Disable; 1: Enable.
76	         */
77	        uint32_t int_enable:1;
78	        uint32_t dma_enable:1;
79	        /** read_wait : R/W; bitpos: [6]; default: 0;
80	         *  For sending read-wait to SDIO cards.
81	         */
82	        uint32_t read_wait:1;
83	        /** send_irq_response : R/W; bitpos: [7]; default: 0;
84	         *  Bit automatically clears once response is sent. To wait for MMC card interrupts,
85	         *  host issues CMD40 and waits for interrupt response from MMC card(s). In the
86	         *  meantime, if host wants SD/MMC to exit waiting for interrupt state, it can set this
87	         *  bit, at which time SD/MMC command state-machine sends CMD40 response on bus and
88	         *  returns to idle state.
89	         */
90	        uint32_t send_irq_response:1;
91	        /** abort_read_data : R/W; bitpos: [8]; default: 0;
92	         *  After a suspend-command is issued during a read-operation, software polls the card
93	         *  to find when the suspend-event occurred. Once the suspend-event has occurred,
94	         *  software sets the bit which will reset the data state machine that is waiting for
95	         *  the next block of data. This bit is automatically cleared once the data state
96	         *  machine is reset to idle.
97	         */
98	        uint32_t abort_read_data:1;
99	        /** send_ccsd : R/W; bitpos: [9]; default: 0;
100	         *  When set, SD/MMC sends CCSD to the CE-ATA device. Software sets this bit only if
101	         *  the current command is expecting CCS (that is, RW_BLK), and if interrupts are
102	         *  enabled for the CE-ATA device. Once the CCSD pattern is sent to the device, SD/MMC
103	         *  automatically clears the SDHOST_SEND_CCSD bit. It also sets the Command Done (CD)
104	         *  bit  in the SDHOST_RINTSTS_REG register, and generates an interrupt for the host,
105	         *  in case the Command Done interrupt is not masked.
106	         *  NOTE: Once the SDHOST_SEND_CCSD bit is set, it takes two card clock cycles to drive
107	         *  the CCSD on the CMD line. Due to this, within the boundary conditions the CCSD may
108	         *  be sent to the CE-ATA device, even if the device has signalled CCS.
109	         */
110	        uint32_t send_ccsd:1;
111	        /** send_auto_stop_ccsd : R/W; bitpos: [10]; default: 0;
112	         *  Always Set SDHOST_SEND_AUTO_STOP_CCSD and SDHOST_SEND_CCSD bits together;
113	         *  SDHOST_SEND_AUTO_STOP_CCSD should not be set independently of send_ccsd. When set,
114	         *  SD/MMC automatically sends an internally-generated STOP command (CMD12) to the
115	         *  CE-ATA device. After sending this internally-generated STOP command, the Auto
116	         *  Command Done (ACD) bit in SDHOST_RINTSTS_REG is set and an interrupt is generated
117	         *  for the host, in case the ACD interrupt is not masked. After sending the Command
118	         *  Completion Signal Disable (CCSD), SD/MMC automatically clears the
119	         *  SDHOST_SEND_AUTO_STOP_CCSD bit.
120	         */
121	        uint32_t send_auto_stop_ccsd:1;
122	        /** ceata_device_interrupt_status : R/W; bitpos: [11]; default: 0;
123	         *  Software should appropriately write to this bit after the power-on reset or any
124	         *  other reset to the CE-ATA device. After reset, the CE-ATA device's interrupt is
125	         *  usually disabled (nIEN = 1). If the host enables the CE-ATA device's interrupt,
126	         *  then software should set this bit.
127	         */
128	        uint32_t ceata_device_interrupt_status:1;
129	        uint32_t reserved2:4;
130	        uint32_t card_voltage_a:4;
131	        uint32_t card_voltage_b:4;
132	        uint32_t enable_od_pullup:1;
133	        uint32_t use_internal_dma:1;
134	        uint32_t reserved3:6;
135	    };
136	    uint32_t val;
137	} sdhost_ctrl_reg_t;
