140	/** Group: Clock divider configuration register */
141	/** Type of clkdiv register
142	 *  Clock divider configuration register
143	 */
144	typedef union {
145	    struct {
146	        /** clk_divider0 : R/W; bitpos: [7:0]; default: 0;
147	         *  Clock divider0 value. Clock divisor is 2*n, where n = 0 bypasses the divider
148	         *  (divisor of 1). For example, a value of 1 means divided by 2*1 = 2, a value of 0xFF
149	         *  means divided by 2*255 = 510, and so on.
150	         */
151	        uint32_t clk_divider0:8;
152	        /** clk_divider1 : R/W; bitpos: [15:8]; default: 0;
153	         *  Clock divider1 value. Clock divisor is 2*n, where n = 0 bypasses the divider
154	         *  (divisor of 1). For example, a value of 1 means divided by 2*1 = 2, a value of 0xFF
155	         *  means divided by 2*255 = 510, and so on.
156	         */
157	        uint32_t clk_divider1:8;
158	        /** clk_divider2 : R/W; bitpos: [23:16]; default: 0;
159	         *  Clock divider2 value. Clock divisor is 2*n, where n = 0 bypasses the divider
160	         *  (divisor of 1). For example, a value of 1 means divided by 2*1 = 2, a value of 0xFF
161	         *  means divided by 2*255 = 510, and so on.
162	         */
163	        uint32_t clk_divider2:8;
164	        /** clk_divider3 : R/W; bitpos: [31:24]; default: 0;
165	         *  Clock divider3 value. Clock divisor is 2*n, where n = 0 bypasses the divider
166	         *  (divisor of 1). For example, a value of 1 means divided by 2*1 = 2, a value of 0xFF
167	         *  means divided by 2*255 = 510, and so on.
168	         */
169	        uint32_t clk_divider3:8;
170	    };
171	    uint32_t val;
172	} sdhost_clkdiv_reg_t;
