175	/** Group: Clock source selection register */
176	/** Type of clksrc register
177	 *  Clock source selection register
178	 */
179	typedef union {
180	    struct {
181	        /** clksrc_reg : R/W; bitpos: [3:0]; default: 0;
182	         *  Clock divider source for two SD cards is supported. Each card has two bits assigned
183	         *  to it. For example, bit[1:0] are assigned for card 0, bit[3:2] are assigned for
184	         *  card 1. Card 0 maps and internally routes clock divider[0:3] outputs to
185	         *  cclk_out[1:0] pins, depending on bit value.
186	         *  00 : Clock divider 0;
187	         *  01 : Clock divider 1;
188	         *  10 : Clock divider 2;
189	         *  11 : Clock divider 3.
190	         */
191	        uint32_t card0:2;
192	        uint32_t card1:2;
193	        uint32_t reserved_4:28;
194	    };
195	    uint32_t val;
196	} sdhost_clksrc_reg_t;
197	
