199	/** Group: Clock enable register */
200	/** Type of clkena register
201	 *  Clock enable register
202	 */
203	typedef union {
204	    struct {
205	        /** cclk_enable : R/W; bitpos: [1:0]; default: 0;
206	         *  Clock-enable control for two SD card clocks and one MMC card clock is supported.
207	         *  One bit per card.
208	         *  0: Clock disabled;
209	         *  1: Clock enabled.
210	         */
211	        uint32_t cclk_enable:2;
212	        uint32_t reserved_2:14;
213	        /** lp_enable : R/W; bitpos: [17:16]; default: 0;
214	         *  Disable clock when the card is in IDLE state. One bit per card.
215	         *  0: clock disabled;
216	         *  1: clock enabled.
217	         */
218	        uint32_t lp_enable:2;
219	        uint32_t reserved_18:14;
220	    };
221	    uint32_t val;
222	} sdhost_clkena_reg_t;
