225	/** Group: Data and response timeout configuration register */
226	/** Type of tmout register
227	 *  Data and response timeout configuration register
228	 */
229	typedef union {
230	    struct {
231	        /** response_timeout : R/W; bitpos: [7:0]; default: 64;
232	         *  Response timeout value. Value is specified in terms of number of card output
233	         *  clocks, i.e., sdhost_cclk_out.
234	         */
235	        uint32_t response_timeout:8;
236	        /** data_timeout : R/W; bitpos: [31:8]; default: 16777215;
237	         *  Value for card data read timeout. This value is also used for data starvation by
238	         *  host timeout. The timeout counter is started only after the card clock is stopped.
239	         *  This value is specified in number of card output clocks, i.e. sdhost_cclk_out of
240	         *  the selected card.
241	         *  NOTE: The software timer should be used if the timeout value is in the order of 100
242	         *  ms. In this case, read data timeout interrupt needs to be disabled.
243	         */
244	        uint32_t data_timeout:24;
245	    };
246	    uint32_t val;
247	} sdhost_tmout_reg_t;
