250	/** Group: Card bus width configuration register */
251	/** Type of ctype register
252	 *  Card bus width configuration register
253	 */
254	typedef union {
255	    struct {
256	        /** card_width : R/W; bitpos: [1:0]; default: 0;
257	         *  One bit per card indicates if card is 1-bit or 4-bit mode.
258	         *  0: 1-bit mode;
259	         *  1: 4-bit mode.
260	         *  Bit[1:0] correspond to card[1:0] respectively.
261	         */
262	        uint32_t card_width:2;
263	        uint32_t reserved_2:14;
264	        /** card_width_8 : R/W; bitpos: [17:16]; default: 0;
265	         *  One bit per card indicates if card is in 8-bit mode.
266	         *  0: Non 8-bit mode;
267	         *  1: 8-bit mode.
268	         *  Bit[17:16] correspond to card[1:0] respectively.
269	         */
270	        uint32_t card_width_8:2;
271	        uint32_t reserved_18:14;
272	    };
273	    uint32_t val;
274	} sdhost_ctype_reg_t;
