278	/** Type of blksiz register
279	 *  Card data block size configuration register
280	 */
281	typedef union {
282	    struct {
283	        /** block_size : R/W; bitpos: [15:0]; default: 512;
284	         *  Block size.
285	         */
286	        uint32_t block_size:16;
287	        uint32_t reserved_16:16;
288	    };
289	    uint32_t val;
290	} sdhost_blksiz_reg_t;
