293	/** Group: Data transfer length configuration register */
294	/** Type of bytcnt register
295	 *  Data transfer length configuration register
296	 */
297	typedef union {
298	    struct {
299	        /** byte_count : R/W; bitpos: [31:0]; default: 512;
300	         *  Number of bytes to be transferred, should be an integral multiple of Block Size for
301	         *  block transfers. For data transfers of undefined byte lengths, byte count should be
302	         *  set to 0. When byte count is set to 0, it is the responsibility of host to
303	         *  explicitly send stop/abort command to terminate data transfer.
304	         */
305	        uint32_t byte_count:32;
306	    };
307	    uint32_t val;
308	} sdhost_bytcnt_reg_t;
