311	/** Group: SDIO interrupt mask register */
312	/** Type of intmask register
313	 *  SDIO interrupt mask register
314	 */
315	typedef union {
316	    struct {
317	        /** int_mask : R/W; bitpos: [15:0]; default: 0;
318	         *  These bits used to mask unwanted interrupts. A value of 0 masks interrupt, and a
319	         *  value of 1 enables the interrupt.
320	         *  Bit 15 (EBE): End-bit error/no CRC error;
321	         *  Bit 14 (ACD): Auto command done;
322	         *  Bit 13 (SBE/BCI): Rx Start Bit Error;
323	         *  Bit 12 (HLE): Hardware locked write error;
324	         *  Bit 11 (FRUN): FIFO underrun/overrun error;
325	         *  Bit 10 (HTO): Data starvation-by-host timeout;
326	         *  Bit 9 (DRTO): Data read timeout;
327	         *  Bit 8 (RTO): Response timeout;
328	         *  Bit 7 (DCRC): Data CRC error;
329	         *  Bit 6 (RCRC): Response CRC error;
330	         *  Bit 5 (RXDR): Receive FIFO data request;
331	         *  Bit 4 (TXDR): Transmit FIFO data request;
332	         *  Bit 3 (DTO): Data transfer over;
333	         *  Bit 2 (CD): Command done;
334	         *  Bit 1 (RE): Response error;
335	         *  Bit 0 (CD): Card detect.
336	         */
337	        uint32_t int_mask:16;
338	        /** sdio_int_mask : R/W; bitpos: [17:16]; default: 0;
339	         *  SDIO interrupt mask, one bit for each card. Bit[17:16] correspond to card[15:0]
340	         *  respectively. When masked, SDIO interrupt detection for that card is disabled. 0
341	         *  masks an interrupt, and 1 enables an interrupt.
342	         */
343	        uint32_t sdio_int_mask:2;
344	        uint32_t reserved_18:14;
345	    };
346	    uint32_t val;
347	} sdhost_intmask_reg_t;
