350	/** Group: Command and boot configuration register */
351	/** Type of cmd register
352	 *  Command and boot configuration register
353	 */
354	typedef union {
355	    struct {
356	        /** cmd_index : R/W; bitpos: [5:0]; default: 0;
357	         *  Command index.
358	         */
359	        uint32_t cmd_index:6;
360	        /** response_expect : R/W; bitpos: [6]; default: 0;
361	         *  0: No response expected from card; 1: Response expected from card.
362	         */
363	        uint32_t response_expect:1;
364	        /** response_long : R/W; bitpos: [7]; default: 0;
365	         *  0: Short response expected from card; 1: Long response expected from card.
366	         */
367	        uint32_t response_long:1;
368	        /** check_response_crc : R/W; bitpos: [8]; default: 0;
369	         *  0: Do not check; 1: Check response CRC.
370	         *  Some of command responses do not return valid CRC bits. Software should disable CRC
371	         *  checks for those commands in order to disable CRC checking by controller.
372	         */
373	        uint32_t check_response_crc:1;
374	        /** data_expected : R/W; bitpos: [9]; default: 0;
375	         *  0: No data transfer expected; 1: Data transfer expected.
376	         */
377	        uint32_t data_expected:1;
378	        /** rw : R/W; bitpos: [10]; default: 0;
379	         *  0: Read from card; 1: Write to card.
380	         *  Don't care if no data is expected from card.
381	         */
382	        uint32_t rw:1;
383	        /** transfer_mode : R/W; bitpos: [11]; default: 0;
384	         *  0: Block data transfer command; 1: Stream data transfer command.
385	         *  Don't care if no data expected.
386	         */
387	        uint32_t transfer_mode:1;
388	        /** send_auto_stop : R/W; bitpos: [12]; default: 0;
389	         *  0: No stop command is sent at the end of data transfer; 1: Send stop command at the
390	         *  end of data transfer.
391	         */
392	        uint32_t send_auto_stop:1;
393	        /** wait_complete : R/W; bitpos: [13]; default: 0;
394	         *  0: Send command at once, even if previous data transfer has not completed; 1: Wait
395	         *  for previous data transfer to complete before sending Command.
396	         *  The SDHOST_WAIT_COMPLETE] = 0 option is typically used to query status of
397	         *  card during data transfer or to stop current data transfer. SDHOST_CARD_NUMBERr
398	         *  should be same as in previous command.
399	         */
400	        uint32_t wait_complete:1;
401	        /** stop_abort_cmd : R/W; bitpos: [14]; default: 0;
402	         *  0: Neither stop nor abort command can stop current data transfer. If abort is sent
403	         *  to function-number currently selected or not in data-transfer mode, then bit should
404	         *  be set to 0; 1: Stop or abort command intended to stop current data transfer in
405	         *  progress.
406	         *  When open-ended or predefined data transfer is in progress, and host issues stop or
407	         *  abort command to stop data transfer, bit should be set so that command/data
408	         *  state-machines of CIU can return correctly to idle state.
409	         */
410	        uint32_t stop_abort_cmd:1;
411	        /** send_init : R/W; bitpos: [15]; default: 0;
412	         *  0: Do not send initialization sequence (80 clocks of 1) before sending this
413	         *  command; 1: Send initialization sequence before sending this command.
414	         *  After powered on, 80 clocks must be sent to card for initialization before sending
415	         *  any commands to card. Bit should be set while sending first command to card so that
416	         *  controller will initialize clocks before sending command to card.
417	         */
418	        uint32_t send_init:1;
419	        /** card_num : R/W; bitpos: [20:16]; default: 0;
420	         *  Card number in use. Represents physical slot number of card being accessed. In
421	         *  SD-only mode, up to two cards are supported.
422	         */
423	        uint32_t card_num:5;
424	        /** update_clk_reg : R/W; bitpos: [21]; default: 0;
425	         *  0: Normal command sequence; 1: Do not send commands, just update clock register
426	         *  value into card clock domain.
427	         *  Following register values are transferred into card clock domain: CLKDIV, CLRSRC,
428	         *  and CLKENA.
429	         *  Changes card clocks (change frequency, truncate off or on, and set low-frequency
430	         *  mode). This is provided in order to change clock frequency or stop clock without
431	         *  having to send command to cards. During normal command sequence, when
432	         *  sdhost_update_clock_registers_only = 0, following control registers are transferred
433	         *  from BIU to CIU: CMD, CMDARG, TMOUT, CTYPE, BLKSIZ, and BYTCNT. CIU uses new
434	         *  register values for new command sequence to card(s). When bit is set, there are no
435	         *  Command Done interrupts because no command is sent to SD_MMC_CEATA cards.
436	         */
437	        uint32_t update_clk_reg:1;
438	        /** read_ceata_device : R/W; bitpos: [22]; default: 0;
439	         *  Read access flag.
440	         *  0: Host is not performing read access (RW_REG or RW_BLK)towards CE-ATA device;
441	         *  1: Host is performing read access (RW_REG or RW_BLK) towards CE-ATA device.
442	         *  Software should set this bit to indicate that CE-ATA device is being accessed for
443	         *  read transfer. This bit is used to disable read data timeout indication while
444	         *  performing CE-ATA read transfers. Maximum value of I/O transmission delay can be no
445	         *  less than 10 seconds. SD/MMC should not indicate read data timeout while waiting
446	         *  for data from CE-ATA device.
447	         */
448	        uint32_t read_ceata_device:1;
449	        /** ccs_expected : R/W; bitpos: [23]; default: 0;
450	         *  Expected Command Completion Signal (CCS) configuration.
451	         *  0: Interrupts are not enabled in CE-ATA device (nIEN = 1 in ATA control register),
452	         *  or command does not expect CCS from device;
453	         *  1: Interrupts are enabled in CE-ATA device (nIEN = 0), and RW_BLK command expects
454	         *  command completion signal from CE-ATA device.
455	         *  If the command expects Command Completion Signal (CCS) from the CE-ATA device, the
456	         *  software should set this control bit. SD/MMC sets Data Transfer Over (DTO) bit in
457	         *  RINTSTS register and generates interrupt to host if Data Transfer Over interrupt is
458	         *  not masked.
459	         */
460	        uint32_t ccs_expected:1;
461	        uint32_t reserved_24:4;
462	        /** volt_switch : R/W; bitpos: [28]; default: 0;
463	         *  Voltage switch bit.
464	         *  0: No voltage switching.
465	         *  1: Voltage switching enabled; must be set for CMD11 only.
466	         */
467	        uint32_t volt_switch:1;
468	        /** use_hole_reg : R/W; bitpos: [29]; default: 1;
469	         *  Use Hold Register.
470	         *  0: CMD and DATA sent to card bypassing HOLD Register;
471	         *  1: CMD and DATA sent to card through the HOLD Register.
472	         */
473	        uint32_t use_hold_reg:1;
474	        uint32_t reserved_30:1;
475	        /** start_command : R/W; bitpos: [31]; default: 0;
476	         *  Start command. Once command is served by the CIU, this bit is automatically
477	         *  cleared. When this bit is set, host should not attempt to write to any command
478	         *  registers. If a write is attempted, hardware lock error is set in raw interrupt
479	         *  register. Once command is sent and a response is received from SD_MMC_CEATA cards,
480	         *  Command Done bit is set in the raw interrupt Register.
481	         */
482	        uint32_t start_command:1;
483	    };
484	    uint32_t val;
485	} sdhost_cmd_reg_t;
