488	/** Group: Response data register */
489	/** Type of resp0 register
490	 *  Response data register
491	 */
492	typedef union {
493	    struct {
494	        /** response0_reg : RO; bitpos: [31:0]; default: 0;
495	         *  Bit[31:0] of response.
496	         */
