503	/** Group: Long response data register */
504	/** Type of resp1 register
505	 *  Long response data register
506	 */
507	typedef union {
508	    struct {
509	        /** response1_reg : RO; bitpos: [31:0]; default: 0;
510	         *  Bit[63:32] of long response.
